import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=path=>readFileSync(path,'utf8');
const inbox=read('app/admin/whatsapp/inbox/page.tsx');
const api=read('app/api/admin/whatsapp/inbox/[threadId]/route.ts');
const index=read('app/api/admin/whatsapp/inbox/route.ts');
const doc=read('docs/WHATSAPP_FREE_FIRST_COST_GUARD.md');
assert(inbox.includes('Incoming messages ON · Paid sending OFF'));
assert(inbox.includes('first 1,000 each month per number free; then ₹0.115'));
assert(inbox.includes('Marketing/promotional templates: ₹0.8631'));
assert(inbox.includes('outbound customer sends and paid templates remain disabled.'));
assert(inbox.includes('cannot verify how much of Meta\'s number-wide monthly free allowance remains'));
assert(inbox.includes('Meta\'s official pricing and current rate card'));
assert(api.includes("payload.action!=='save_draft'"),'Inbox must refuse all sending actions');
assert(api.includes('canSend:false'),'Inbox may not advertise enabled sending');
assert(index.includes('outboundEnabled:false'),'Conversation list may not advertise enabled sending');
assert(doc.includes('provider-verified remaining-quota counter'));
assert(doc.includes('No paid sends without fresh, explicit spending approval'));
assert(doc.includes('Tree planting is parked'));
console.log('PASS WhatsApp free-first charges disclosure, zero paid-sending UI/API protections and parked planting policy.');
